.canvas {
      position: relative;
      min-height: 14rem;
      border: 2px dashed var(--is-border);
      border-radius: var(--is-radius);
      background:
        repeating-linear-gradient(45deg,
          color-mix(in srgb, var(--is-bg-elev) 60%, transparent) 0 8px,
          transparent 8px 16px);
      display: grid; place-items: center;
      color: var(--is-text-soft);
      font-size: .85rem;
      cursor: context-menu;
    }
    .log {
      font-family: ui-monospace, monospace;
      font-size: .8rem;
      background: var(--is-bg-elev);
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius);
      padding: .55rem .75rem;
      margin-top: .85rem;
      max-height: 9rem;
      overflow: auto;
    }

blocks.code:
const menu = document.querySelector('is-context-menu');
menu.openAt(x, y);   // programa el menú en una posición
menu.close();
menu.isOpen;

menu.addEventListener('is-select', e => {
  console.log('elegido:', e.detail.value);   // valor de data-value o texto
  console.log('item:', e.detail.item);
});

// items via slot
<is-context-menu for="#canvas">
  <button class="item" data-value="open">Abrir</button>
  <button class="item" data-value="delete">Eliminar</button>
</is-context-menu>
